extern void hz_run(uint64_t *results, const uint64_t *consts);

static uint64_t run_hazards(void)
{
  uint64_t *r = results[hart_id()];
  unsigned bad = 0, first = 0;

  __asm__ volatile ("csrs mstatus, %0" :: "r"(1ULL << 13));   /* FS = Initial */
  hz_run(r, hz_consts);
  for (unsigned i = 0; i < NUM_CASES; i++)
    if (r[i] != expected[i]) {
#ifdef DEBUG_DUMP
      /* failing cases at 0x0010_9000 + hart*0x800: {index, got, expected} */
      if (bad < 40) {
        volatile uint64_t *d = (volatile uint64_t *)(0x00109000UL + hart_id() * 0x800UL + bad * 24UL);
        d[0] = i; d[1] = r[i]; d[2] = expected[i];
      }
#endif
      if (bad == 0)
        first = i + 1;
      bad++;
    }
  return bad ? (((uint64_t)bad << 16) | first) : 0;
}

static void start_main(void);

/* Initialize the stack before entering C code. */
__attribute__((naked, section(".text.start"), used))
void _start(void)
{
  __asm__ volatile (
    DUAL_CORE_STACK_INIT
    "jal ra, start_main\n"
    "1: j 1b\n"
  );
}

static void start_main(void)
{
  tohost_exit(run_hazards());
}
